#[path = "C:/Users/a/RustroverProjects/GlobalSim/src/retail_physics.rs"] mod retail_physics;
use retail_physics::{Parameters, TargetSpeed, Acceleration, advance_start_delay, finish_time, phase_boundaries};
const DT:f32=0.066600002348423;
#[derive(Clone,Copy)] struct R{time:f32,pos:f32,lane:f32,speed:f32,hp:f32,delay:f32,phase:usize,dash:bool,finished:bool,finish:f32,min:f32,front:i32,gap:f32,side:bool,rank:i32,ft:f64,st:f64,at:f64}
fn limit(g:f32)->f32{let n=(g/2.)*0.6_f32;((1_f64-n as f64)*0.0416666716337204_f64)as f32}
fn snapshot(a:&mut[R;3]){for o in 0..3{let mut best=f32::INFINITY;let mut who=-1;let mut rank=1;let mut side=false;for i in 0..3{if a[i].pos>a[o].pos||(a[i].pos==a[o].pos&&i<o){rank+=1}if i==o{continue}let g=a[i].pos-a[o].pos;let lane=(a[i].lane-a[o].lane).abs();if g>0.&&g<2.&&(g<best||(g==best&&(i as i32)<who))&&lane<=limit(g){best=g;who=i as i32}if !a[i].finished&&g.abs()<1.0499999523162842&&lane<0.1111110970377922&&lane!=0.{side=true}}a[o].front=who;a[o].gap=if who<0{f32::NAN}else{best};a[o].side=side;a[o].rank=rank}}
fn tick_one(p:&Parameters,a:&mut[R;3],i:usize,truncated:bool){if truncated||a[i].finished||a[i].pos>=1200.{return}let mut min=if a[i].dash{3.}else{p.minimum_speed(900.,1200.)};if !a[i].dash&&a[i].front>=0{min=min.min(a[a[i].front as usize].min)}a[i].min=min;let(delay,gate)=advance_start_delay(a[i].delay,DT);a[i].delay=delay;let Some(frac)=gate else{a[i].time+=DT;return};let(_,tp)=retail_physics::target_speed_indices(a[i].pos,1200.);let base=p.base_target_speed(1000.,1,tp,1.,1200.);let target=p.target_speed(TargetSpeed{base,section:0.,pace:1.,force_in:0.,power:1000.,moving_lane_skill:false,slope:0.,downhill:false,hp_remaining:a[i].hp>0.,minimum:min},&[]);let acc=if a[i].hp<=0.{-1.2}else if a[i].speed>target{[-1.2,-0.8,-1.][a[i].phase]}else{p.acceleration(Acceleration{power:1000.,strategy:1,phase:a[i].phase,ground:1.,distance:1.,uphill:false,start_dash:a[i].dash},&[])};let mut s=a[i].speed+acc*DT;s=if a[i].speed<=target{s.min(target)}else{s.max(target)};let dash=p.start_dash_speed(1200.);if a[i].dash{s=s.min(dash)}if a[i].front>=0{s=s.min(p.blocking_speed_cap(min,a[a[i].front as usize].speed,a[i].gap))}s=s.max(min);a[i].speed=s;let drain=if a[i].dash{20.}else{p.hp_per_second(s,p.course_speed(1200.),1.,900.,a[i].phase,1.)};a[i].hp=(a[i].hp-drain*DT).max(0.);a[i].phase=phase_boundaries(1200.).iter().filter(|&&b|a[i].pos>=b).count().min(2);let old=a[i].pos;a[i].pos+=((s*DT)as f64*frac)as f32;a[i].time+=DT;if old<1200.&&a[i].pos>=1200.{a[i].finished=true;a[i].finish=finish_time(a[i].time,DT,old,a[i].pos,1200.)}if a[i].dash&&s>=dash{a[i].dash=false}}
fn emit(a:&[R;3],tr:bool){print!("[");for(i,x)in a.iter().enumerate(){if i>0{print!(",")}print!("[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]",x.time.to_bits(),x.pos.to_bits(),x.speed.to_bits(),x.hp.to_bits(),x.delay.to_bits(),x.phase,x.dash as u8,x.finish.to_bits(),x.min.to_bits(),x.front,x.gap.to_bits(),x.side as u8,x.rank,x.ft.to_bits(),x.st.to_bits(),x.at.to_bits(),x.finished as u8,tr as u8,i)}print!("]")}
fn runner(pos:f32,lane:f32,speed:f32,delay:f32)->R{R{time:0.,pos,lane,speed,hp:1000.,delay,phase:0,dash:false,finished:false,finish:f32::NAN,min:3.,front:-1,gap:f32::NAN,side:false,rank:0,ft:0.,st:0.,at:0.}}
fn case(p:&Parameters,name:&str,mut a:[R;3]){print!("{{\"name\":\"{}\",\"lanes_bits\":[{},{},{}],\"initial\":",name,a[0].lane.to_bits(),a[1].lane.to_bits(),a[2].lane.to_bits());emit(&a,false);print!(",\"rows\":[");let mut trunc=false;for t in 0..8{if t>0{print!(",")}if !trunc{snapshot(&mut a);for i in 0..3{let f=a[i].front>=0;a[i].ft=if f{a[i].ft+DT as f64}else{0.};a[i].st=if a[i].side{a[i].st+DT as f64}else{0.};a[i].at=if f&&a[i].side{a[i].at+DT as f64}else{0.};}}for i in 0..3{tick_one(p,&mut a,i,trunc)}trunc|=a.iter().any(|x|x.finished);emit(&a,trunc)}print!("]}}")}
fn main(){let root=json::parse(&std::fs::read_to_string("C:/Users/a/PycharmProjects/GlobalSim-Jax/globalsim_jax/global_parameters.json").unwrap()).unwrap();let p=Parameters::from_value(root.get("parameters").unwrap()).unwrap();print!("{{\"revision\":\"58da7bc4693d9aa8f6340e348cba1c5b5fb5a856\",\"rank_label\":\"pre_movement\",\"dt_bits\":{},\"inputs\":{{\"distance_bits\":{},\"guts_bits\":{},\"power_bits\":{},\"speed_stat_bits\":{},\"strategy\":1,\"aptitude_bits\":{},\"ground_bits\":{}}},\"cases\":[",DT.to_bits(),1200f32.to_bits(),900f32.to_bits(),1000f32.to_bits(),1000f32.to_bits(),1f32.to_bits(),1f32.to_bits());case(&p,"higher_blocker",[runner(10.,0.,18.,0.),runner(11.,0.,8.,0.),runner(30.,0.,20.,0.)]);print!(",");case(&p,"lower_blocker_delayed",[runner(11.,0.02,28.,0.),runner(10.,0.,30.,0.02),runner(30.,0.,20.,0.)]);print!(",");case(&p,"closed_gate",[runner(11.,0.02,28.,0.),runner(10.,0.,30.,0.1),runner(30.,0.,20.,0.)]);println!("]}}");}
